#include "community.h"
#include <string.h>

typedef struct { const char *p,*end; unsigned depth; } Json;
static void ws(Json *j){while(j->p<j->end&&(*j->p==' '||*j->p=='\t'||*j->p=='\r'||*j->p=='\n'))j->p++;}
static bool hex4(Json *j,unsigned *v){if((size_t)(j->end-j->p)<4)return false;unsigned n=0;for(unsigned i=0;i<4;i++){unsigned char c=(unsigned char)j->p[i];unsigned d=c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:16;if(d>15)return false;n=(n<<4)|d;}j->p+=4;*v=n;return true;}
static bool append_utf8(char *out,size_t cap,size_t *n,unsigned cp){unsigned char b[4];size_t z;if(cp<0x80){b[0]=(unsigned char)cp;z=1;}else if(cp<0x800){b[0]=(unsigned char)(0xc0|(cp>>6));b[1]=(unsigned char)(0x80|(cp&63));z=2;}else if(cp<0x10000){b[0]=(unsigned char)(0xe0|(cp>>12));b[1]=(unsigned char)(0x80|((cp>>6)&63));b[2]=(unsigned char)(0x80|(cp&63));z=3;}else{b[0]=(unsigned char)(0xf0|(cp>>18));b[1]=(unsigned char)(0x80|((cp>>12)&63));b[2]=(unsigned char)(0x80|((cp>>6)&63));b[3]=(unsigned char)(0x80|(cp&63));z=4;}if(out&&*n+z>=cap)return false;if(out)memcpy(out+*n,b,z);*n+=z;return true;}
static bool string(Json *j,char *out,size_t cap){ws(j);if(j->p==j->end||*j->p++!='"')return false;size_t n=0;while(j->p<j->end){unsigned char c=(unsigned char)*j->p++;if(c=='"'){if(out){if(n>=cap)return false;out[n]=0;}return true;}if(c<0x20)return false;if(c=='\\'){if(j->p==j->end)return false;c=(unsigned char)*j->p++;if(c=='"'||c=='\\'||c=='/'){}else if(c=='b')c=' ';else if(c=='f'||c=='n'||c=='r'||c=='t')c=' ';else if(c=='u'){unsigned cp;if(!hex4(j,&cp)||cp<0x20||cp==0x7f)return false;if(cp>=0xd800&&cp<=0xdbff){unsigned low;if(j->end-j->p<6||j->p[0]!='\\'||j->p[1]!='u')return false;j->p+=2;if(!hex4(j,&low)||low<0xdc00||low>0xdfff)return false;cp=0x10000+((cp-0xd800)<<10)+(low-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)return false;if(!append_utf8(out,cap,&n,cp))return false;continue;}else return false;}if(out){if(n+1>=cap)return false;out[n]=(char)c;}n++;}return false;}
static bool number(Json *j,unsigned *out){ws(j);if(j->p==j->end||*j->p<'0'||*j->p>'9')return false;unsigned n=0;do{unsigned d=(unsigned)(*j->p++-'0');if(n>(0xffffffffu-d)/10u)return false;n=n*10u+d;}while(j->p<j->end&&*j->p>='0'&&*j->p<='9');*out=n;return true;}
static bool nullable_string(Json *j,char *out,size_t cap){ws(j);if(j->end-j->p>=4&&!memcmp(j->p,"null",4)){j->p+=4;if(cap)out[0]=0;return true;}return string(j,out,cap);}
static bool skip(Json *j);
static bool array_skip(Json *j){if(++j->depth>16)return false;j->p++;ws(j);if(j->p<j->end&&*j->p==']'){j->p++;j->depth--;return true;}for(;;){if(!skip(j))return false;ws(j);if(j->p==j->end)return false;if(*j->p==']'){j->p++;j->depth--;return true;}if(*j->p++!=',')return false;}}
static bool object_skip(Json *j){if(++j->depth>16)return false;j->p++;ws(j);if(j->p<j->end&&*j->p=='}'){j->p++;j->depth--;return true;}for(;;){if(!string(j,NULL,0))return false;ws(j);if(j->p==j->end||*j->p++!=':')return false;if(!skip(j))return false;ws(j);if(j->p==j->end)return false;if(*j->p=='}'){j->p++;j->depth--;return true;}if(*j->p++!=',')return false;}}
static bool skip(Json *j){ws(j);if(j->p==j->end)return false;switch(*j->p){case '"':return string(j,NULL,0);case '{':return object_skip(j);case '[':return array_skip(j);case 't':if(j->end-j->p>=4&&!memcmp(j->p,"true",4)){j->p+=4;return true;}return false;case 'f':if(j->end-j->p>=5&&!memcmp(j->p,"false",5)){j->p+=5;return true;}return false;case 'n':if(j->end-j->p>=4&&!memcmp(j->p,"null",4)){j->p+=4;return true;}return false;default:{unsigned n;return number(j,&n);}}}
static bool artist_object(Json *j,char *name,size_t cap){ws(j);if(j->p==j->end||*j->p++!='{')return false;bool found=false;ws(j);if(j->p<j->end&&*j->p=='}'){j->p++;return false;}for(;;){char key[24];if(!string(j,key,sizeof(key)))return false;ws(j);if(j->p==j->end||*j->p++!=':')return false;ws(j);if(!strcmp(key,"name")){if(found||!string(j,name,cap))return false;found=true;}else if(!skip(j))return false;ws(j);if(j->p==j->end)return false;if(*j->p=='}'){j->p++;return found;}if(*j->p++!=',')return false;}}
static bool art_object(Json *j,PdCommunityArt *a){
    ws(j);if(j->p==j->end||*j->p++!='{')return false;bool id=false,title=false,artist=false,w=false,h=false,status=false;ws(j);if(j->p<j->end&&*j->p=='}'){j->p++;return false;}
    for(;;){char key[24];if(!string(j,key,sizeof(key)))return false;ws(j);if(j->p==j->end||*j->p++!=':')return false;ws(j);
        if(!strcmp(key,"id")){if(id||!string(j,a->id,sizeof(a->id))||!a->id[0])return false;id=true;for(const char *p=a->id;*p;p++)if(!((*p>='a'&&*p<='z')||(*p>='0'&&*p<='9')||*p=='-'))return false;}
        else if(!strcmp(key,"title")){if(title||!string(j,a->title,sizeof(a->title)))return false;title=true;}
        else if(!strcmp(key,"artist")){if(artist||!artist_object(j,a->artist,sizeof(a->artist)))return false;artist=true;}
        else if(!strcmp(key,"status")){if(status||!string(j,a->status,sizeof(a->status)))return false;status=true;}
        else if(!strcmp(key,"reason")){if(!nullable_string(j,a->reason,sizeof(a->reason)))return false;}
        else if(!strcmp(key,"width")){if(w||!number(j,&a->width)||a->width<1||a->width>1920)return false;w=true;}
        else if(!strcmp(key,"height")){if(h||!number(j,&a->height)||a->height<1||a->height>1080)return false;h=true;}
        else if(!skip(j))return false;ws(j);if(j->p==j->end)return false;
        if(*j->p=='}'){j->p++;return id&&title&&w&&h&&(artist||status);}if(*j->p++!=',')return false;
    }
}
static bool items_array(Json *j,PdCommunityPage *page){ws(j);if(j->p==j->end||*j->p++!='[')return false;ws(j);if(j->p<j->end&&*j->p==']'){j->p++;return true;}for(;;){if(page->count>=PD_COMMUNITY_PAGE||!art_object(j,&page->items[page->count]))return false;page->count++;ws(j);if(j->p==j->end)return false;if(*j->p==']'){j->p++;return true;}if(*j->p++!=',')return false;}}
bool pd_community_parse_page(const char *json,size_t size,PdCommunityPage *page){if(!json||!page||!size||size>16384)return false;memset(page,0,sizeof(*page));Json j={json,json+size,0};ws(&j);if(j.p==j.end||*j.p++!='{')return false;bool items=false,total=false,next=false;ws(&j);if(j.p<j.end&&*j.p=='}')return false;for(;;){char key[24];if(!string(&j,key,sizeof(key)))return false;ws(&j);if(j.p==j.end||*j.p++!=':')return false;ws(&j);if(!strcmp(key,"items")){if(items||!items_array(&j,page))return false;items=true;}else if(!strcmp(key,"total")){if(total||!number(&j,&page->total))return false;total=true;page->has_total=true;}else if(!strcmp(key,"nextOffset")){if(next)return false;next=true;if(j.end-j.p>=4&&!memcmp(j.p,"null",4)){j.p+=4;page->has_next=false;}else if(number(&j,&page->next_offset))page->has_next=true;else return false;}else if(!strcmp(key,"profileRequired")){if(j.end-j.p>=4&&!memcmp(j.p,"true",4)){page->profile_required=true;j.p+=4;}else if(j.end-j.p>=5&&!memcmp(j.p,"false",5))j.p+=5;else return false;}else if(!skip(&j))return false;ws(&j);if(j.p==j.end)return false;if(*j.p=='}'){j.p++;break;}if(*j.p++!=',')return false;}ws(&j);return j.p==j.end&&items&&next;}
